import re
from dataclasses import dataclass
from pathlib import Path

from forge_kit.errors import KitError

KIT_DIR = ".forge"
KIT_PREFIX = "forge-"
TARGETS_DIR = "targets"
WORK_DIR = "work"
ROUNDS_DIR = "rounds"
FINAL_DIR = "final"
BUILD_DIR = "build"
CLAUDE_DIR = ".claude"
SKILLS_DIR = "skills"
AGENTS_DIR = "agents"
REFERENCES_DIR = "references"
SKILL_FILE = "SKILL.md"
AGENT_SUFFIX = ".md"
