    def stream_path(self, slot: Slot, run_id: str) -> Path:
        return self.out_dir(slot, run_id) / STREAM_FILE

    def stderr_path(self, slot: Slot, run_id: str) -> Path:
        return self.out_dir(slot, run_id) / STDERR_FILE

    def exec_path(self, slot: Slot, run_id: str) -> Path:
        return self.out_dir(slot, run_id) / EXEC_FILE

    def facts_path(self, slot: Slot, run_id: str) -> Path:
        return self.out_dir(slot, run_id) / FACTS_FILE

    def trace_md_path(self, slot: Slot, run_id: str) -> Path:
        return self.out_dir(slot, run_id) / TRACE_MD

    def result_md_path(self, slot: Slot, run_id: str) -> Path:
        return self.out_dir(slot, run_id) / RESULT_MD

    def patch_path(self, slot: Slot, run_id: str) -> Path:
        return self.out_dir(slot, run_id) / PATCH_FILE

    def grader_prompt_path(self, slot: Slot, run_id: str) -> Path:
        return self.out_dir(slot, run_id) / GRADER_PROMPT_FILE

    def grade_path(self, slot: Slot, run_id: str) -> Path:
        return self.out_dir(slot, run_id) / GRADE_FILE

    def analyst_prompt_path(self, round_no: int) -> Path:
        return self.round_dir(round_no) / ANALYST_PROMPT_FILE

    def proposal_path(self, round_no: int) -> Path:
        return self.round_dir(round_no) / PROPOSAL_FILE

    def proposal_md_path(self, round_no: int) -> Path:
        return self.round_dir(round_no) / PROPOSAL_MD

    def proposed_dir(self, round_no: int) -> Path:
        """分析役が直す候補のバンドル。skills/<スキル名>/ と agents/ を持つ。"""
        return self.round_dir(round_no) / PROPOSED_DIR

    def previous_dir(self, round_no: int) -> Path:
        return self.round_dir(round_no) / PREVIOUS_DIR

    def compare_path(self, round_no: int) -> Path:
        return self.round_dir(round_no) / COMPARE_FILE

    def compare_md_path(self, round_no: int) -> Path:
        return self.round_dir(round_no) / COMPARE_MD

    def decision_path(self, round_no: int) -> Path:
        return self.round_dir(round_no) / DECISION_FILE


def make_layout(root: Path, target: str, copies_root: Path) -> Layout:
    if not TARGET_ID.match(target):
        raise KitError(f"--target は kebab-case（小文字・数字・ハイフン）にしてください（今: {target}）")
    return Layout(root.resolve(), target, copies_root)


def run_id(task_id: str, agent_no: int) -> str:
    return f"{task_id}-a{agent_no}"


def agent_file(agent_name: str) -> str:
    return agent_name + AGENT_SUFFIX


def is_matched(path: str, patterns: tuple[str, ...]) -> bool:
    """パスが glob のどれかに当たるか。* は / もまたぐ（`.github/*` は下の全ファイルに当たる）。"""
    return any(fnmatch.fnmatchcase(path, pattern) for pattern in patterns)

"""作業領域のファイルから今の段階を求め、次に実行するコマンドか、起動するサブエージェントか、人に聞くことを示す。"""

from __future__ import annotations

from forge_kit import bundle, charter, contracts, render, workspace
from forge_kit.errors import InvalidFileError
from forge_kit.layout import Layout

CLI = "python3 .forge/forge.py"
GOALS = "（forge-goals）"
BUILD = "（forge-build）"
RUN = "（forge-run）"
# status の行の書き出し。スキルはこの書き出しで行を読み分けるので、新しい種類を足さない（OPS-01）
LINE_KINDS = (
    "対象:",
    "段階:",
    "改善のラウンド:",
    "次:",
    "その後:",
    "問題が出たら:",
    "承認なら:",
    "直すなら:",
    "採用なら:",
    "不採用なら:",
    "job ",
)
FEEDBACK = "'<直してほしいこと>'"
LAUNCH = "次: 下の job をすべて Agent ツールで1つのメッセージにまとめて起動し、全員の完了を待つ"


def _command(name: str, where: Layout, extra: str = "") -> str:
    return f"{CLI} {name} --target {where.target}{extra}"


def _build_steps(where: Layout, progress: workspace.BuildProgress) -> list[str]:
    if not progress.designer_prompted:
        return [f"段階: 設計の準備{BUILD}", f"次: {_command('design-new', where)}"]
    if not progress.designed:
        return [
            f"段階: 設計役の作業{BUILD}",
            LAUNCH,
            render.job(contracts.AGENTS["designer"], "design", str(where.designer_prompt_path)),
            f"その後: {_command('design-check', where)}",
        ]
    if not progress.design_checked:
        return [
            f"段階: 設計の検査{BUILD}",
            f"次: {_command('design-check', where)}",
            "問題が出たら: 問題の一覧を添えて設計役をもう一度起動し、終わったら design-check をやり直す",
        ]
    if progress.design_state != "approved":
        return [
            f"段階: 設計の確認（人が決める）{BUILD}",
            f"次: {where.design_md_path} を人に見せ、承認するかを聞く",
            f"承認なら: {_command('design-approve', where)}",
            "直すなら: " + _command("design-new", where, f" --feedback {FEEDBACK}"),
        ]
    return _draft_steps(where, progress)


def _draft_steps(where: Layout, progress: workspace.BuildProgress) -> list[str]:
    if not progress.builder_prompted:
        return [f"段階: 構築の準備{BUILD}", f"次: {_command('build', where)}"]
    if not progress.bundle_checked:
        return [
            f"段階: 構築役の作業{BUILD}",
            LAUNCH,
            render.job(contracts.AGENTS["builder"], "build", str(where.builder_prompt_path)),
            f"その後: {_command('bundle-check', where)}",
            "問題が出たら: 問題の一覧を添えて構築役をもう一度起動し、終わったら bundle-check をやり直す",
        ]
    return [
        f"段階: 下書きの確認（人が決める）{BUILD}",
        f"次: {where.bundle_check_md_path} と {where.draft_dir} の下書きを人に見せ、入れるかを聞く",
        f"承認なら: {_command('install', where)}",
        "直すなら: " + _command("build", where, " --feedback '<直してほしいこと>'"),
    ]


def _slot_args(slot: workspace.SlotProgress) -> str:
    if slot.slot.variant == "final":
        return " --variant final"
    return f" --variant {slot.slot.variant} --round {slot.slot.round_no}"


def _slot_steps(where: Layout, slot: workspace.SlotProgress, label: str) -> list[str]:
    """1回の評価の次の手。評価が採点まで終わっていれば空。"""
    args = _slot_args(slot)
    if not slot.planned:
        return [f"段階: {label}の準備{RUN}", f"次: {_command('prepare', where, args)}"]
    if slot.pending_runs:
        return [
            f"段階: {label}の実行（未実行 {len(slot.pending_runs)} 件）{RUN}",
            f"次: {_command('execute', where, args)}",
            f"その後: {_command('collect', where, args)}",
        ]
    if not slot.collected:
        return [f"段階: {label}の集計の準備{RUN}", f"次: {_command('collect', where, args)}"]
    if slot.pending_grades:
        jobs = [
            render.job(contracts.AGENTS["grader"], run.run_id, str(where.grader_prompt_path(slot.slot, run.run_id)))
            for run in slot.pending_grades
        ]
        return [
            f"段階: {label}の採点（採点が無い実行 {len(jobs)} 件）{RUN}",
            LAUNCH,
            *jobs,
            f"その後: {_command('score', where, args)}",
        ]
    if not slot.scored:
        return [f"段階: {label}の集計{RUN}", f"次: {_command('score', where, args)}"]
    return []


def _round_steps(where: Layout, item: workspace.RoundProgress) -> list[str]:
    number = item.round_no
    label = f"{number} 回目の改善"
    round_arg = f" --round {number}"
    if not item.proposed:
        return [
            f"段階: {label}の分析{RUN}",
            LAUNCH,
            render.job(contracts.AGENTS["analyst"], f"round-{number}", str(where.analyst_prompt_path(number))),
            f"その後: {_command('propose', where, round_arg)}",
        ]
    if not item.checked:
        return [
            f"段階: {label}の提案の検査{RUN}",
            f"次: {_command('propose', where, round_arg)}",
            "問題が出たら: 問題の一覧を添えて分析役をもう一度起動し、終わったら propose をやり直す",
        ]
    if not item.has_changes:
        return [
            f"段階: {label}（バンドルの変更が無い提案）{RUN}",
            f"次: {where.proposal_md_path(number)} の所見を人に見せる",
            f"その後: {_command('decide', where, round_arg + ' --reject')}",
        ]
    steps = _slot_steps(where, item.candidate, f"{label}の候補の評価")
    if steps:
        return steps
    if not item.compared:
        return [f"段階: {label}の比較{RUN}", f"次: {_command('compare', where, round_arg)}"]
    return [
        f"段階: {label}の採否（人が決める）{RUN}",
        f"次: {where.compare_md_path(number)} と {where.proposal_md_path(number)} を人に見せ、採用するかを聞く",
        f"採用なら: {_command('decide', where, round_arg + ' --adopt')}",
        f"不採用なら: {_command('decide', where, round_arg + ' --reject')}",
    ]


def _run_steps(where: Layout, model: charter.Charter, progress: workspace.Progress) -> list[str]:
    steps = _slot_steps(where, progress.baseline, "最初の評価")
    if steps:
        return steps
    open_round = next((item for item in progress.rounds if item.decision is None), None)
    if open_round is not None:
        return _round_steps(where, open_round)
    current = workspace.load_scores(where, progress.current_slot)
    if not current.all_must_met and progress.decided_rounds < model.budget.max_rounds:
        number = progress.decided_rounds + 1
        return [f"段階: {number} 回目の改善の準備{RUN}", f"次: {_command('analyze', where, f' --round {number}')}"]
    steps = _slot_steps(where, progress.final, "最後の評価（ホールドアウトを含む）")
    if steps:
        return steps
    if not progress.reported:
        return [f"段階: 報告{RUN}", f"次: {_command('report', where)}"]
    return [f"段階: 完了{RUN}", f"次: {where.report_path} を人に見せる"]


def _evaluation(where: Layout, model: charter.Charter) -> list[str]:
    problems = bundle.check(where.claude_dir, model.target.skill_name)
    if problems:
        return [
            f"段階: 対象スキルがバンドルの決まりを満たしていない{RUN}",
            *[f"  - {problem}" for problem in problems],
            f"次: 問題を人に見せ、{where.bundle_rules_path} に沿って直すかを相談する",
        ]
    progress = workspace.progress(where, model)
    rounds = f"改善のラウンド: {progress.decided_rounds} / {model.budget.max_rounds} 回が決定済み"
    return [rounds, *_run_steps(where, model, progress)]


def status(where: Layout) -> str:
    if not where.charter_path.is_file():
        return "\n".join([f"段階: charter が無い{GOALS}", "次: /forge-goals で、人とゴール・指標・評価課題を決める"])
    try:
        data, model = workspace.load_charter(where)
    except InvalidFileError as exc:
        return "\n".join([f"段階: charter に問題がある{GOALS}", exc.message, "次: /forge-goals で直す"])
    header = f"対象: {model.target.id}（スキル {model.target.skill_name}）"
    state = charter.approval_state(data, model)
    if state != "approved":
        reason = "未承認" if state == "unapproved" else "承認の後に変更された"
        return "\n".join([header, f"段階: charter が{reason}{GOALS}", "次: /forge-goals で人に確かめ、承認を記録する"])
    if not workspace.has_skill(where, model):
        return "\n".join([header, *_build_steps(where, workspace.build_progress(where, model))])
    return "\n".join([header, *_evaluation(where, model)])

"""集めた事実と採点役の判定から、charter の指標を計算して scores.json と scores.md を書く。"""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass
from typing import Callable

from forge_kit import catalog, charter, contracts, fsops, metrics, render, workspace
from forge_kit.errors import InvalidFileError, KitError, StageError
from forge_kit.layout import Layout, Slot


@dataclass(frozen=True)
class RunData:
    run: contracts.Run
    facts: contracts.Facts
    grade: contracts.Grade | None


def _is_met(data: RunData, key: str) -> bool:
    return data.grade is not None and any(item.key == key and item.met for item in data.grade.items)


def _share(data: RunData, prefix: str) -> float | None:
    """grade の中で prefix で始まる項目のうち、満たした割合。該当する項目が無ければ None。"""
    items = [item for item in data.grade.items if item.key.startswith(prefix)] if data.grade else []
    return sum(1.0 for item in items if item.met) / len(items) if items else None


def _shares(runs: Sequence[RunData], prefix: str) -> float | None:
    return metrics.mean([value for value in (_share(run, prefix) for run in runs) if value is not None])


def _delegation(runs: Sequence[RunData]) -> float | None:
    """編集のうちサブエージェントが行った割合を実行ごとに出して平均する。編集の無い実行は数えない。"""
    shares = [metrics.ratio(run.facts.edits_sub, run.facts.edits_sub + run.facts.edits_main) for run in runs]
    return metrics.mean([share for share in shares if share is not None])


def _known(values: Sequence[float | None]) -> float | None:
    return metrics.mean([value for value in values if value is not None])


Calculator = Callable[[Sequence[RunData]], "float | None"]
# カタログの指標ごとの、1つの課題での値の求め方。指標を足したら、ここと catalog.METRICS を一緒に変える
CALCULATORS: dict[str, Calculator] = {
    "check_pass": lambda runs: metrics.rate([run.facts.check_exit == 0 for run in runs]),
    "acceptance": lambda runs: _shares(runs, charter.ACCEPTANCE_KEY + ":"),
    "protected_untouched": lambda runs: metrics.rate([not run.facts.protected_changed for run in runs]),
    "completion": lambda runs: metrics.rate([run.facts.completed for run in runs]),
    "delegation": _delegation,
    "flow_conformance": lambda runs: _shares(runs, charter.STEP_KEY + ":"),
    "report_format": lambda runs: metrics.rate([_is_met(run, charter.REPORT_KEY) for run in runs]),
    "files_agreement": lambda runs: metrics.pairwise_agreement([frozenset(r.facts.changed_files) for r in runs]),
    "cost_usd": lambda runs: _known([run.facts.cost_usd for run in runs]),
    "duration_sec": lambda runs: _known([run.facts.duration_sec for run in runs]),
    "launches": lambda runs: metrics.mean([float(len(run.facts.launches)) for run in runs]),
}


def task_value(metric_id: str, runs: Sequence[RunData]) -> float | None:
    if catalog.is_custom(metric_id):
        return metrics.rate([_is_met(run, metric_id) for run in runs])
    return CALCULATORS[metric_id](runs)


def metric_scores(
    model: charter.Charter, task_ids: Sequence[str], runs: Sequence[RunData]
) -> tuple[contracts.MetricScore, ...]:
    scores = []
    for choice in model.metrics:
        metric = charter.definition(choice)
        by_task = tuple(
            contracts.TaskValue(task_id, task_value(choice.id, [r for r in runs if r.run.task_id == task_id]))
            for task_id in task_ids
        )
        value = metrics.mean([entry.value for entry in by_task if entry.value is not None])
        scores.append(
            contracts.MetricScore(
                id=choice.id,
                name=metric.name,
                priority=choice.priority,
                direction=metric.direction,
                threshold=choice.threshold,
                value=value,
                met=metrics.is_met(value, choice.threshold, metric.direction),
                by_task=by_task,
            )
        )
    return tuple(scores)


def _run_data(where: Layout, model: charter.Charter, slot: Slot, plan: contracts.Plan) -> list[RunData]:
    graded = charter.has_grader_items(model)
    runs, problems = [], []
    for run in plan.runs:
        facts = workspace.load_facts(where, slot, run.run_id)
        grade = None
        if graded:
            try:
                grade = workspace.load_grade(where, slot, run.run_id)
            except KitError as exc:
                problems.append(f"{run.run_id}: {exc.message}")
        runs.append(RunData(run, facts, grade))
    if problems:
        raise InvalidFileError(
            "採点役の出力", [*problems, "上の実行の採点役を、同じプロンプトでもう一度起動してください"]
        )
    return runs


def run_notes(data: RunData) -> tuple[str, ...]:
    facts, notes = data.facts, []
    if not facts.completed:
        notes.append("打ち切り" if facts.timed_out else "最後まで終えなかった")
    if facts.check_exit not in (None, 0):
        notes.append(f"検査が失敗（終了コード {facts.check_exit}）")
    if facts.protected_changed:
        notes.append(f"保護パスを変更: {', '.join(facts.protected_changed)}")
    if not facts.launches:
        notes.append("サブエージェントを起動しなかった")
    if facts.edits_main:
        notes.append(f"メインのセッションが {facts.edits_main} 回編集した")
    if facts.denials:
        notes.append(f"拒否された操作: {', '.join(facts.denials)}")
    for item in data.grade.items if data.grade else ():
        if not item.met:
            notes.append(f"{item.key} 未達: {item.evidence}")
    return tuple(notes)


def score(where: Layout, slot: Slot) -> str:
    model, sha = workspace.approved_charter(where)
    plan = workspace.load_plan(where, slot)
    if plan.charter_sha256 != sha:
        raise StageError(
            f"charter が {slot.name} の準備の後に変わりました。作業領域を消して prepare からやり直してください"
        )
    runs = _run_data(where, model, slot, plan)
    task_ids = list(dict.fromkeys(run.task_id for run in plan.runs))
    visible = [task_id for task_id in task_ids if not charter.is_holdout(task_id)]
    holdout = [task_id for task_id in task_ids if charter.is_holdout(task_id)]
    scores = contracts.Scores(
        slot=slot.name,
        variant=slot.variant,
        round_no=slot.round_no,
        charter_sha256=sha,
        metrics=metric_scores(model, visible, runs),
        holdout_metrics=metric_scores(model, holdout, runs) if holdout else (),
        run_notes=tuple(contracts.RunNote(r.run.run_id, r.run.task_id, run_notes(r)) for r in runs),
    )
    fsops.write_json(where.scores_path(slot), contracts.to_data(scores))
    fsops.write_text(where.scores_md_path(slot), render_scores(scores))
    fsops.write_text(where.summary_md_path(slot), summary_table(scores.metrics))
    verdict = "must の指標は全部達成" if scores.all_must_met else "must の指標に未達がある"
    return "\n".join([f"採点しました: {slot.name}（{verdict}）", summary_table(scores.metrics)])


def summary_table(scores: Sequence[contracts.MetricScore]) -> str:
    rows = [
        [s.id, s.name, s.priority, render.number(s.value), render.number(s.threshold), render.mark(s.met)]
        for s in scores
    ]
    return render.table(["id", "名前", "優先度", "値", "閾値", "判定"], rows)


def render_scores(scores: contracts.Scores) -> str:
    parts = [f"# {scores.slot} の採点", "", "## 指標", "", summary_table(scores.metrics), ""]
    if scores.metrics and scores.metrics[0].by_task:
        headers = ["id", *[entry.task_id for entry in scores.metrics[0].by_task]]
        rows = [[s.id, *[render.number(entry.value) for entry in s.by_task]] for s in scores.metrics]
        parts += ["## 課題ごとの値", "", render.table(headers, rows), ""]
    if scores.holdout_metrics:
        parts += ["## ホールドアウトの課題での値", "", summary_table(scores.holdout_metrics), ""]
    parts += ["## 実行ごとの所見", ""]
    for note in scores.run_notes:
        parts.append(f"### {note.run_id}\n\n{render.bullets(note.notes)}\n")
    return "\n".join(parts)

"""charter（人と合意したゴール・指標・評価課題・環境・実行の条件・予算・承認）のモデルと検証、承認のハッシュを扱う。"""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass

from forge_kit import catalog, shape
from forge_kit.errors import InvalidFileError

SCHEMA_VERSION = 1
TOP_KEYS = (
    "schema_version",
    "target",
    "purpose",
    "owner",
    "goals",
    "metrics",
    "environment",
    "executor",
    "tasks",
    "budget",
    "approval",
)
NAME = r"[a-z0-9]+(?:-[a-z0-9]+)*"
GOAL_ID = r"G[1-9][0-9]*"
TASK_ID = r"[TH][1-9][0-9]*"
HOLDOUT_PREFIX = "H"
KIT_PREFIX = "forge-"
SHA256 = r"[0-9a-f]{64}"
ISO_DATE = r"[0-9]{4}-[0-9]{2}-[0-9]{2}"
AGENTS_BOUNDS = (1, 10)
ROUNDS_BOUNDS = (1, 10)
CHECK_TIMEOUT_BOUNDS = (10, 7200)
EXECUTOR_TIMEOUT_BOUNDS = (60, 7200)
PARALLEL_BOUNDS = (1, 20)
BUDGET_USD_MAX = 100.0
DEFAULT_AGENTS = 3
DEFAULT_MAX_ROUNDS = 3
DEFAULT_CHECK_TIMEOUT_SEC = 600
DEFAULT_EXECUTOR_TIMEOUT_SEC = 1800
DEFAULT_PARALLEL = 3
DEFAULT_BUDGET_USD = 3.0
ACCEPTANCE_KEY = "acceptance"
STEP_KEY = "step"
REPORT_KEY = "report"
REPORT_CRITERION = "最後の返答が、SKILL.md の `## 報告` の定め（書く項目と順序）に従っている"


@dataclass(frozen=True)
class Target:
    id: str
    skill_name: str


@dataclass(frozen=True)
class Goal:
    id: str
    statement: str
    metrics: tuple[str, ...]


@dataclass(frozen=True)
class MetricChoice:
    """charter で選んだ指標。criterion は独自の指標（custom_<n>）だけが持つ。"""

    id: str
    threshold: float
    priority: str
    criterion: str


@dataclass(frozen=True)
class Environment:
    check_command: str
    check_timeout_sec: int
    protected_paths: tuple[str, ...]
    skip_dirs: tuple[str, ...]
    link_dirs: tuple[str, ...]


@dataclass(frozen=True)
class Executor:
    """実行役（claude -p）の条件。model が空なら Claude Code の既定のモデルを使う。"""

    model: str
    allowed_tools: tuple[str, ...]
    max_budget_usd: float
    timeout_sec: int
    parallel: int


@dataclass(frozen=True)
class Task:
    id: str
    prompt: str
    acceptance: tuple[str, ...]


@dataclass(frozen=True)
class Budget:
    agents: int
    max_rounds: int


@dataclass(frozen=True)
class Approval:
    sha256: str
    approved_on: str


@dataclass(frozen=True)
class Charter:
    schema_version: int
    target: Target
    purpose: str
    owner: str
    goals: tuple[Goal, ...]
    metrics: tuple[MetricChoice, ...]
    environment: Environment
    executor: Executor
    tasks: tuple[Task, ...]
    budget: Budget
    approval: Approval | None


def parse(data: object, source: str) -> Charter:
    """charter.json の中身を検証してモデルにする。問題は全部集めてから InvalidFileError にする。"""
    problems: list[str] = []
    root = shape.as_object(data, "", problems)
    shape.unknown_keys(root, TOP_KEYS, "", problems)
    charter = Charter(
        schema_version=shape.integer(root, "schema_version", "", problems, bounds=(SCHEMA_VERSION, SCHEMA_VERSION)),
        target=_target(root, problems),
        purpose=shape.filled(root, "purpose", "", problems),
        owner=shape.text(root, "owner", "", problems),
        goals=_goals(root, problems),
        metrics=_metrics(root, problems),
        environment=_environment(root, problems),
        executor=_executor(root, problems),
        tasks=_tasks(root, problems),
        budget=_budget(root, problems),
        approval=_approval(root, problems),
    )
    if not problems:
        _check_relations(charter, problems)
    if problems:
        raise InvalidFileError(source, problems)
    return charter


def _target(root: dict[str, object], problems: list[str]) -> Target:
    data = shape.as_object(root.get("target"), "target", problems)
    shape.unknown_keys(data, ("id", "skill_name"), "target", problems)
    skill_name = shape.text(data, "skill_name", "target", problems, pattern=NAME)
    if skill_name.startswith(KIT_PREFIX):
        problems.append(f"target.skill_name は {KIT_PREFIX} で始めないでください（この道具のスキルと区別するため）")
    return Target(id=shape.text(data, "id", "target", problems, pattern=NAME), skill_name=skill_name)


def _goals(root: dict[str, object], problems: list[str]) -> tuple[Goal, ...]:
    goals = []
    for where, data in shape.objects(root, "goals", "", problems):
        shape.unknown_keys(data, ("id", "statement", "metrics"), where, problems)
        goals.append(
            Goal(
                id=shape.text(data, "id", where, problems, pattern=GOAL_ID),
                statement=shape.filled(data, "statement", where, problems),
                metrics=shape.texts(data, "metrics", where, problems),
            )
        )
    if not goals:
        problems.append("goals が空です。人と決めたゴールを1件以上書いてください")
    for goal_id in shape.duplicates(goal.id for goal in goals):
        problems.append(f"goals の id {goal_id} が重複しています")
    return tuple(goals)


def _metrics(root: dict[str, object], problems: list[str]) -> tuple[MetricChoice, ...]:
    choices = []
    for where, data in shape.objects(root, "metrics", "", problems):
        shape.unknown_keys(data, ("id", "threshold", "priority", "criterion"), where, problems)
        metric_id = shape.filled(data, "id", where, problems)
        custom = catalog.is_custom(metric_id)
        criterion = shape.filled(data, "criterion", where, problems) if custom else ""
        if not custom and "criterion" in data:
            problems.append(f"{where}.criterion は独自の指標（custom_<番号>）にだけ書きます")
        if not custom and metric_id and catalog.find(metric_id) is None:
            names = ", ".join(metric.id for metric in catalog.METRICS)
            problems.append(f"{where}.id {metric_id!r} はカタログにありません（{names}、custom_<番号>）")
        choice = MetricChoice(
            id=metric_id,
            threshold=shape.real(data, "threshold", where, problems),
            priority=shape.choice(data, "priority", catalog.PRIORITIES, where, problems),
            criterion=criterion,
        )
        _check_threshold(choice, where, problems)
        choices.append(choice)
    if not choices:
        problems.append("metrics が空です。人と決めた指標を1件以上書いてください")
    elif all(choice.priority != "must" for choice in choices):
        problems.append(
            "metrics に priority が must の指標が1件もありません。終わりの判定に使う指標を must にしてください"
        )
    for metric_id in shape.duplicates(choice.id for choice in choices):
        problems.append(f"metrics の id {metric_id} が重複しています")
    return tuple(choices)


def _check_threshold(choice: MetricChoice, where: str, problems: list[str]) -> None:
    metric = None if catalog.is_custom(choice.id) else catalog.find(choice.id)
    upper = catalog.RATE_MAX if metric is None else metric.max_value
    if choice.threshold < 0 or (upper is not None and choice.threshold > upper):
        limit = "0 以上" if upper is None else f"0 以上 {upper} 以下"
        problems.append(f"{where}.threshold は {limit} にしてください（今: {choice.threshold}）")


def _environment(root: dict[str, object], problems: list[str]) -> Environment:
    where = "environment"
    data = shape.as_object(root.get(where), where, problems)
    keys = ("check_command", "check_timeout_sec", "protected_paths", "skip_dirs", "link_dirs")
    shape.unknown_keys(data, keys, where, problems)
    return Environment(
        check_command=shape.text(data, "check_command", where, problems),
        check_timeout_sec=shape.integer(data, "check_timeout_sec", where, problems, bounds=CHECK_TIMEOUT_BOUNDS),
        protected_paths=shape.texts(data, "protected_paths", where, problems),
        skip_dirs=shape.texts(data, "skip_dirs", where, problems),
        link_dirs=shape.texts(data, "link_dirs", where, problems),
    )


def _executor(root: dict[str, object], problems: list[str]) -> Executor:
    where = "executor"
    data = shape.as_object(root.get(where), where, problems)
    shape.unknown_keys(data, ("model", "allowed_tools", "max_budget_usd", "timeout_sec", "parallel"), where, problems)
    budget = shape.real(data, "max_budget_usd", where, problems)
    if not 0 < budget <= BUDGET_USD_MAX:
        problems.append(f"{where}.max_budget_usd は 0 より大きく {BUDGET_USD_MAX} 以下にしてください（今: {budget}）")
    return Executor(
        model=shape.text(data, "model", where, problems, pattern=r"[A-Za-z0-9.\[\]_-]*"),
        allowed_tools=shape.texts(data, "allowed_tools", where, problems),
        max_budget_usd=budget,
        timeout_sec=shape.integer(data, "timeout_sec", where, problems, bounds=EXECUTOR_TIMEOUT_BOUNDS),
        parallel=shape.integer(data, "parallel", where, problems, bounds=PARALLEL_BOUNDS),
    )


def _tasks(root: dict[str, object], problems: list[str]) -> tuple[Task, ...]:
    tasks = []
    for where, data in shape.objects(root, "tasks", "", problems):
        shape.unknown_keys(data, ("id", "prompt", "acceptance"), where, problems)
        tasks.append(
            Task(
                id=shape.text(data, "id", where, problems, pattern=TASK_ID),
                prompt=shape.filled(data, "prompt", where, problems),
                acceptance=shape.texts(data, "acceptance", where, problems),
            )
        )
    for task_id in shape.duplicates(task.id for task in tasks):
        problems.append(f"tasks の id {task_id} が重複しています")
    return tuple(tasks)


def _budget(root: dict[str, object], problems: list[str]) -> Budget:
    data = shape.as_object(root.get("budget"), "budget", problems)
    shape.unknown_keys(data, ("agents", "max_rounds"), "budget", problems)
    return Budget(
        agents=shape.integer(data, "agents", "budget", problems, bounds=AGENTS_BOUNDS),
        max_rounds=shape.integer(data, "max_rounds", "budget", problems, bounds=ROUNDS_BOUNDS),
    )


def _approval(root: dict[str, object], problems: list[str]) -> Approval | None:
    if root.get("approval") is None:
        return None
    data = shape.as_object(root.get("approval"), "approval", problems)
    shape.unknown_keys(data, ("sha256", "approved_on"), "approval", problems)
    return Approval(
        sha256=shape.text(data, "sha256", "approval", problems, pattern=SHA256),
        approved_on=shape.text(data, "approved_on", "approval", problems, pattern=ISO_DATE),
    )


def _check_relations(charter: Charter, problems: list[str]) -> None:
    """項目どうしの関係（ゴールと指標の対応、指標の前提、評価課題）を確かめる。"""
    _check_goals(charter, problems)
    _check_prerequisites(charter, problems)


def _check_goals(charter: Charter, problems: list[str]) -> None:
    chosen = {choice.id for choice in charter.metrics}
    referenced: set[str] = set()
    for goal in charter.goals:
        if not goal.metrics:
            problems.append(f"ゴール {goal.id} に指標がありません。測る指標を1つ以上結び付けてください")
        for metric_id in goal.metrics:
            referenced.add(metric_id)
            if metric_id not in chosen:
                problems.append(f"ゴール {goal.id} の指標 {metric_id} が metrics にありません")
    for metric_id in sorted(chosen - referenced):
        problems.append(f"指標 {metric_id} がどのゴールにも結び付いていません")


def _check_prerequisites(charter: Charter, problems: list[str]) -> None:
    chosen = {choice.id for choice in charter.metrics}
    if not visible_tasks(charter):
        problems.append("tasks に、ホールドアウト（H<番号>）ではない課題（T<番号>）を1件以上書いてください")
    if "check_pass" in chosen and not charter.environment.check_command.strip():
        problems.append("check_pass を使うには environment.check_command が要ります")
    if "protected_untouched" in chosen and not charter.environment.protected_paths:
        problems.append("protected_untouched を使うには environment.protected_paths が要ります")
    if "acceptance" in chosen:
        for task in charter.tasks:
            if not task.acceptance:
                problems.append(f"acceptance を使うには、課題 {task.id} の acceptance が1件以上要ります")
    if chosen & catalog.AGREEMENT_METRICS and charter.budget.agents < 2:
        problems.append("一致度の指標は2人以上を比べるため、budget.agents を 2 以上にしてください")


def is_holdout(task_id: str) -> bool:
    return task_id.startswith(HOLDOUT_PREFIX)


def visible_tasks(charter: Charter) -> tuple[Task, ...]:
    return tuple(task for task in charter.tasks if not is_holdout(task.id))


def slot_tasks(charter: Charter, *, include_holdout: bool) -> tuple[Task, ...]:
    return charter.tasks if include_holdout else visible_tasks(charter)


def definition(choice: MetricChoice) -> catalog.Metric:
    if catalog.is_custom(choice.id):
        return catalog.custom_metric(choice.id, choice.criterion)
    metric = catalog.find(choice.id)
    if metric is None:
        raise InvalidFileError("charter", [f"指標 {choice.id} がカタログにありません"])
    return metric


def has_grader_items(charter: Charter) -> bool:
    return any(definition(choice).method == "grader" for choice in charter.metrics)


def grade_items(charter: Charter, task_id: str, steps: tuple[str, ...]) -> tuple[tuple[str, str], ...]:
    """採点役が1つの実行について判定する項目の（キー, 判定の条件）。steps は SKILL.md の `## 手順` の項目。"""
    chosen = {choice.id for choice in charter.metrics}
    items: list[tuple[str, str]] = []
    task = next(task for task in charter.tasks if task.id == task_id)
    if "acceptance" in chosen:
        items += [(f"{ACCEPTANCE_KEY}:{number}", text) for number, text in enumerate(task.acceptance, 1)]
    if "flow_conformance" in chosen:
        items += [(f"{STEP_KEY}:{number}", text) for number, text in enumerate(steps, 1)]
    if "report_format" in chosen:
        items.append((REPORT_KEY, REPORT_CRITERION))
    items += [(choice.id, choice.criterion) for choice in charter.metrics if catalog.is_custom(choice.id)]
    return tuple(items)


def fragments(charter: Charter, min_chars: int) -> frozenset[str]:
    """評価課題の文（課題文と受け入れ条件の行）。スキルに写すと、課題にだけ効く改善（過剰適合）になる。"""
    texts: list[str] = []
    for task in charter.tasks:
        texts += [task.prompt, *task.acceptance]
    return frozenset(line.strip() for text in texts for line in text.splitlines() if len(line.strip()) >= min_chars)


def skeleton(target_id: str, skill_name: str) -> dict[str, object]:
    """対話の出発点になる charter。推奨の指標を既定の閾値で並べ、人と決める項目は空にしておく。"""
    metrics = [
        {"id": metric.id, "threshold": metric.default_threshold, "priority": "must"}
        for metric in catalog.METRICS
        if metric.recommended
    ]
    environment = {
        "check_command": "",
        "check_timeout_sec": DEFAULT_CHECK_TIMEOUT_SEC,
        "protected_paths": [],
        "skip_dirs": [],
        "link_dirs": [],
    }
    executor = {
        "model": "",
        "allowed_tools": [],
        "max_budget_usd": DEFAULT_BUDGET_USD,
        "timeout_sec": DEFAULT_EXECUTOR_TIMEOUT_SEC,
        "parallel": DEFAULT_PARALLEL,
    }
    return {
        "schema_version": SCHEMA_VERSION,
        "target": {"id": target_id, "skill_name": skill_name},
        "purpose": "",
        "owner": "",
        "goals": [],
        "metrics": metrics,
        "environment": environment,
        "executor": executor,
        "tasks": [],
        "budget": {"agents": DEFAULT_AGENTS, "max_rounds": DEFAULT_MAX_ROUNDS},
        "approval": None,
    }


def digest(data: dict[str, object]) -> str:
    """approval を除いた中身のハッシュ。承認の後に1文字でも変えると一致しなくなる。"""
    body = {key: value for key, value in data.items() if key != "approval"}
    canonical = json.dumps(body, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def approval_state(data: dict[str, object], charter: Charter) -> str:
    """approved（承認済みで変更なし）、unapproved（未承認）、stale（承認の後に変えた）のどれか。"""
    if charter.approval is None:
        return "unapproved"
    return "approved" if charter.approval.sha256 == digest(data) else "stale"
